begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','41100000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('41100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','reimbursement-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,6) i;
select pg_temp.login(1);
create temp table ctx as select public.create_project('Notification automation fixture','UTC','GBP','2026-01-01') id;
create temp table cat as with c as(insert into public.project_areas(project_id,title) select id,'Villa' from ctx returning id) select * from c;
set local role postgres;
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.id,('41100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Reimbursement member '||i,case when i=4 then 'viewer' else 'member' end::public.member_role,'active' from ctx,generate_series(2,4) i;
create temp table members as select right(user_id::text,1)::int n,id from public.project_members where project_id=(select id from ctx);
grant select on members to authenticated;
select pg_temp.login(1);
select is((select count(*)::int from public.user_notification_preferences),0,'Missing override defaults enabled');
select pg_temp.login(2);
select lives_ok($$select public.set_my_notification_preference('activities',false)$$,'Member can opt out');
select is((select enabled from public.user_notification_preferences where category='activities'),false,'Owner reads own override');
select throws_ok($$select public.set_my_notification_preference('arbitrary',false)$$,'22023',null,'Unknown category rejected');
select throws_ok($$select public.set_my_notification_preference('payments',null)$$,'22023',null,'Null preference rejected');
select throws_ok($$insert into public.user_notification_preferences(user_id,category,enabled) values('41100000-0000-4000-8000-000000000003','activities',false)$$,'42501',null,'No arbitrary owner insert');
select pg_temp.login(1);
select is((select count(*)::int from public.user_notification_preferences),0,'Organizer cannot read member preferences');
select throws_ok($$update public.user_notification_preferences set enabled=true$$,'42501',null,'Organizer cannot edit member preference');
create temp table activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Per recipient","kind":"other","activity_type":"task"}',null)).id;
set local role postgres;
select is((select count(*)::int from app.domain_events where resource_id=(select id from activity)),1,'Suppression preserves fact');
select is((select count(*)::int from app.domain_event_processing where event_id in(select id from app.domain_events where resource_id=(select id from activity))),1,'Suppression preserves processing');
select is((select count(*)::int from app.automation_action_runs where event_id in(select id from app.domain_events where resource_id=(select id from activity))),1,'Suppression preserves action receipt');
select is((select count(*)::int from public.notifications where commitment_id=(select id from activity)),2,'Other Member and Viewer receive same event');
select is((select count(*)::int from public.notifications where commitment_id=(select id from activity) and recipient_user_id='41100000-0000-4000-8000-000000000002'),0,'Opted-out recipient alone suppressed');
select is((select count(*)::int from app.notification_delivery_receipts where event_id in(select id from app.domain_events where resource_id=(select id from activity)) and outcome='preference_suppressed'),1,'Explicit suppression receipt');
select is((select count(*)::int from app.notification_delivery_receipts where event_id in(select id from app.domain_events where resource_id=(select id from activity)) and outcome='delivered'),2,'Explicit delivery receipts per recipient');
select throws_ok($$delete from app.notification_delivery_receipts$$,'P0001',null,'Delivery receipts immutable');
select app.process_domain_event(id) from app.domain_events where resource_id=(select id from activity);
select is((select count(*)::int from public.notifications where commitment_id=(select id from activity)),2,'Retry does not duplicate');
select pg_temp.login(2);
select public.set_my_notification_preference('activities',true);
select is((select count(*)::int from public.user_notification_preferences),0,'Re-enable removes override');
set local role postgres;
select app.process_domain_event(id) from app.domain_events where resource_id=(select id from activity);
select is((select count(*)::int from public.notifications where commitment_id=(select id from activity)),2,'Re-enable never replays old suppressed event');
select pg_temp.login(1);
create temp table next_activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Future version","kind":"other","activity_type":"task"}',null)).id;
select pg_temp.login(2);
select is((select count(*)::int from public.v_my_notification_inbox where project_id=(select id from ctx)),1,'Future event delivers after re-enable');
select is(public.mark_all_notifications_read(),1,'Mark all affects visible own unread only');
select is(public.mark_all_notifications_read(),0,'Mark all idempotent');
select is((select count(*)::int from public.v_my_notification_inbox where read_at is null and project_id=(select id from ctx)),0,'Own badge cleared');
select pg_temp.login(3);
select is((select count(*)::int from public.v_my_notification_inbox where read_at is null and project_id=(select id from ctx)),2,'Other recipient unread untouched');
select pg_temp.login(5);
select is((select count(*)::int from public.v_my_notification_inbox where project_id=(select id from ctx)),0,'Outsider sees no destinations');
select pg_temp.login(1);
update public.commitments set starts_at=statement_timestamp()+interval '2 days',owner_member_id=(select id from members where n=2) where id=(select id from activity);
create temp table financial_before as select to_jsonb(f) data from public.v_project_financials f where project_id=(select id from ctx);
set local role postgres;
select set_config('request.jwt.claims','{}',true);
select app.evaluate_activity_due_soon();
select is((select count(*)::int from app.domain_events where resource_id=(select id from activity) and event_type='activity.due_soon'),1,'Upcoming Activity emitted');
select is((select count(*)::int from public.notifications where activity_reminder_id=(select id from activity) and kind='activity_due_soon'),1,'Only owner reminded');
select is((select recipient_user_id from public.notifications where activity_reminder_id=(select id from activity) and kind='activity_due_soon'),'41100000-0000-4000-8000-000000000002'::uuid,'Actual assigned recipient');
select app.evaluate_activity_due_soon();
select is((select count(*)::int from public.notifications where activity_reminder_id=(select id from activity) and kind='activity_due_soon'),1,'Repeated evaluation dedupes');
update public.commitments set starts_at=starts_at+interval '1 hour' where id=(select id from activity);
select app.evaluate_activity_due_soon();
select is((select count(*)::int from public.notifications where activity_reminder_id=(select id from activity) and kind='activity_due_soon'),2,'Changed start version delivers');
update public.commitments set starts_at=statement_timestamp()+interval '5 days' where id=(select id from activity);
select is(app.activity_due_soon((select id from activity)),false,'Outside three-day threshold skipped');
update public.commitments set starts_at=statement_timestamp()-interval '1 hour' where id=(select id from activity);
select is(app.activity_due_soon((select id from activity)),false,'Past timed Activity not reminded');
update public.commitments set starts_at=statement_timestamp()+interval '1 day',status='completed' where id=(select id from activity);
select is(app.activity_due_soon((select id from activity)),false,'Completed skipped');
update public.commitments set status='researching' where id=(select id from activity);
update public.commitments set status='cancelled' where id=(select id from activity);
select is(app.activity_due_soon((select id from activity)),false,'Cancelled skipped');
update public.commitments set status='researching',deleted_at=now() where id=(select id from activity);
select is(app.activity_due_soon((select id from activity)),false,'Deleted skipped');
update public.commitments set deleted_at=null,owner_member_id=null,starts_at=statement_timestamp()+interval '1 day' where id=(select id from activity);
select app.evaluate_activity_due_soon();
select is((select count(*)::int from public.notifications where activity_reminder_id=(select id from activity) and kind='activity_due_soon' and recipient_user_id='41100000-0000-4000-8000-000000000001'),1,'Unassigned falls back to Organizer');
select is((select to_jsonb(f) from public.v_project_financials f where project_id=(select id from ctx)),(select data from financial_before),'Reminders preserve financials');
select ok((select bool_and(critical) from app.notification_policy('reimbursement_payment_acknowledged')),'Claim critical');
select ok((select bool_and(critical) from app.notification_policy('reimbursement_payment_acknowledgement_withdrawn')),'Withdrawal critical');
select ok((select bool_and(critical) from app.notification_policy('reimbursement_receipt_confirmed')),'Receipt critical');
select ok((select bool_and(critical) from app.notification_policy('project_member_approved')),'Approval critical');
select pg_temp.login(2);
select throws_ok($$select * from app.notification_delivery_receipts$$,'42501',null,'Delivery internals private');
select throws_ok($$select app.evaluate_scheduled_domain_events()$$,'42501',null,'Client cannot evaluate');
select throws_ok($$select * from app.scheduled_evaluator_runs$$,'42501',null,'Scheduler evidence private');
select ok(not exists(select 1 from public.v_my_notification_inbox where resource_type not in('activity','decision','project') or section not in('payments','reimbursements','people')),'Destination allowlist');
set local role anon;
select throws_ok($$select * from public.user_notification_preferences$$,'42501',null,'Anon preference reads denied');
select throws_ok($$select public.set_my_notification_preference('activities',false)$$,'42501',null,'Anon preference changes denied');
set local role postgres;
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.user_notification_preferences'::regclass),'Preferences FORCE RLS');
-- Critical delivery is verified through the actual financial workflow, not registry flags alone.
select pg_temp.login(1);
select public.set_my_notification_preference('reimbursements',false);
create temp table critical_activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Critical workflow","kind":"other","activity_type":"task","estimated_cost_minor":90000}',null)).id;
select public.set_activity_cost_split((select id from critical_activity),jsonb_build_object('mode','even','cost',90000,'members',(select jsonb_agg(id order by id) from members where n<=3)));
create temp table source_payment as with p as(insert into public.payments(project_id,commitment_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,critical_activity.id,members.id,'full','outgoing','paid',90000,current_date from ctx,critical_activity,members where n=1 returning id) select * from p;
select pg_temp.login(2);
select public.set_my_notification_preference('reimbursements',false);
select pg_temp.login(1);
create temp table critical_request as select public.create_reimbursement((select id from source_payment),(select id from members where n=2),30000) id;
select pg_temp.login(2);
select is((select count(*)::int from public.v_my_reimbursement_notifications where reimbursement_id=(select id from critical_request)),0,'Optional request suppressed');
create temp table critical_ack as select public.acknowledge_reimbursement_payment((select id from critical_request)) id;
select pg_temp.login(1);
select is((select count(*)::int from public.v_my_payment_acknowledgement_notifications where reimbursement_id=(select id from critical_request)),1,'Claim delivered despite creditor opt-out');
select pg_temp.login(2);
select public.withdraw_reimbursement_payment_acknowledgement((select id from critical_ack));
select pg_temp.login(1);
select is((select kind from public.v_my_payment_acknowledgement_notifications where reimbursement_id=(select id from critical_request)),'reimbursement_payment_acknowledgement_withdrawn','Critical withdrawal bypasses opt-out');
select pg_temp.login(2);
create temp table next_ack as select public.acknowledge_reimbursement_payment((select id from critical_request)) id;
select pg_temp.login(1);
select public.confirm_reimbursement_receipt((select id from next_ack));
select pg_temp.login(2);
select is((select count(*)::int from public.v_my_receipt_confirmation_notifications where reimbursement_id=(select id from critical_request)),1,'Critical receipt bypasses debtor opt-out');
select is((select remaining_minor from public.v_activity_member_settlements where commitment_id=(select id from critical_activity) and member_id=(select id from members where n=2)),0::bigint,'Preferences do not block settlement');
select is((select count(*)::int from public.payments where commitment_id=(select id from critical_activity) and settlement_group_id is not null),2,'Exactly one authoritative pair');
set local role postgres;
select set_config('request.jwt.claims','{}',true);
update public.projects set timezone='Pacific/Kiritimati' where id=(select id from ctx);
update public.commitments set starts_at=(((statement_timestamp() at time zone 'Pacific/Kiritimati')::date+3)::timestamp at time zone 'Pacific/Kiritimati'),is_all_day=true where id=(select id from activity);
select is(app.activity_due_soon((select id from activity)),true,'Project-local midnight within three-day window');
update public.commitments set starts_at=starts_at+interval '1 day' where id=(select id from activity);
select is(app.activity_due_soon((select id from activity)),false,'Project-local day four excluded');
update public.commitments set starts_at=starts_at-interval '1 day' where id=(select id from activity);
update public.projects set status='archived' where id=(select id from ctx);
select is(app.activity_due_soon((select id from activity)),false,'Archived project excluded');
update public.projects set status='active' where id=(select id from ctx);
-- Failure in one resource rolls back only that resource; it remains retryable with evidence.
create function pg_temp.fail_one_notification() returns trigger language plpgsql as $$ begin
 if new.kind='activity_due_soon' and new.activity_reminder_id=(select id from activity) then raise exception 'Synthetic scheduler failure' using errcode='22000'; end if; return new;
end $$;
create trigger phase11_failure before insert on public.notifications for each row execute function pg_temp.fail_one_notification();
update public.commitments set starts_at=statement_timestamp()+interval '1 hour',is_all_day=false where id=(select id from activity);
update public.commitments set starts_at=statement_timestamp()+interval '2 hours' where id=(select id from next_activity);
select app.evaluate_activity_due_soon();
select ok(exists(select 1 from app.scheduled_evaluator_runs where resource_id=(select id from activity) and error_code='22000'),'Failure recorded without sensitive exception text');
select is((select count(*)::int from public.notifications where activity_reminder_id=(select id from next_activity)),1,'Good resource still evaluated after poisoned resource');
drop trigger phase11_failure on public.notifications;
select app.evaluate_activity_due_soon();
select ok(exists(select 1 from app.domain_events where resource_id=(select id from activity) and deduplication_key='start:'||(select extract(epoch from starts_at)::text from public.commitments where id=(select id from activity))||':3'),'Failed resource retry succeeds');
select app.evaluate_scheduled_domain_events();
select is((select count(distinct evaluator)::int from app.scheduled_evaluator_runs where error_code is null),3,'All three static evaluators observed');
select pg_temp.login(3);
create temp table victim_notice as select id from public.v_my_notification_inbox where project_id=(select id from ctx) limit 1;
select pg_temp.login(2);
select is(public.mark_notification_read((select id from victim_notice)),null::uuid,'Cannot mark another recipient notice read');
select pg_temp.login(1);
select public.soft_delete_project((select id from ctx));
select pg_temp.login(2);
select is((select count(*)::int from public.v_my_notification_inbox where project_id=(select id from ctx)),0,'Deleted project removes all inbox detail');
select is(public.mark_all_notifications_read(),0,'Mark-all does not touch invisible history');

select * from finish();
rollback;
